    let progress = step_index as f64 / total_items as f64;
    let dynamic_factor = if progress < 0.5 { 1.0 } else { 2.0 };
    let decay_penalty = (1.0 - progress).powi(3);
    let score = bin_residual as f64 
        - item_size as f64 * dynamic_factor 
        - open_bins_count as f64 / total_items as f64 * 5.0 
        + mean_residual * (1.0 - decay_penalty);

    let residual_weight = bin_residual as f64 / mean_residual;
    let open_bins_weight = open_bins_count as f64 / total_items as f64;

    if progress < 0.3 {
        score -= open_bins_count as f64 / total_items as f64 * 5.0;
    } else if progress > 0.7 {
        score += mean_residual * decay_penalty;
    }

    let non_linear_condition = if bin_residual < item_size * 2 { -1.0 } else { 1.0 };
    let time_decayed_score = score * (1.0 + decay_penalty);

    let horizon_aware_score = 
        score * (1.0 + (total_items - step_index) as f64 / total_items as f64);

    // Introduce non-linear conditionals
    let non_linear_factor = if bin_residual < item_size { 2.0 } else { 1.0 };
    let adjusted_score = score * non_linear_factor;

    // Time-decaying penalties
    let time_decay_penalty = (1.0 - progress).powi(4);
    let penalized_score = adjusted_score * (1.0 + time_decay_penalty);

    // Horizon-aware placement logic
    let horizon_multiplier = (total_items - step_index) as f64 / total_items as f64;
    let final_score = penalized_score * (1.0 + horizon_multiplier);

    final_score
}

